      stiffnessNpm: 8.0,
      dampingNspm: 1.4,
      thermalCapacityJpk: 4.0,
      awarenessGrowthRate: 1.8,
      annealRateAlpha: spec.annealRateAlpha,
      flowRestoreRateBeta: 2.4,
      lyapunovCriticalThreshold: 0.18,
    },
    transducer: {
