      downwardSocketId: 'socket:higher-mu-down',
      sieveMdlThresholdBits: 8.3,
      chebyshevOrderK: 12,
      reflexBudgetMs: 0.033,
    },
    evaluator: {
      minCoherenceTarget: 0.95,
      maxFreeEnergyBound: 25.0,
      conservationToleranceJ: 1e-5,
      masteryDurationSec: spec.masteryWindowSec,
    },
  };
}

